#define HWY_COMPILE_ONLY_STATIC

#include "stdlib/blas/ext/base/dsumpw/simd/dsumpw_highway_impl.h"
#include "stdlib/blas/ext/base/dsumpw/simd/dsumpw_highway.h"

namespace stdlib_blas_ext_base_dsumpw {

	static double DispatchDsumpwHighway( const CBLAS_INT N, const double *X, const CBLAS_INT strideX, const CBLAS_INT offsetX ) {
		return HWY_STATIC_DISPATCH( DsumpwHighway )( N, X, strideX, offsetX );
	}

} // end namespace stdlib_blas_ext_base_dsumpw

extern "C" double API_SUFFIX( stdlib_strided_dsumpw_ndarray_highway )( const CBLAS_INT N, const double *X, const CBLAS_INT strideX, const CBLAS_INT offsetX ) {
	return stdlib_blas_ext_base_dsumpw::DispatchDsumpwHighway( N, X, strideX, offsetX );
}
